const pts = [];
const segments = 224;
for (let i = 0; i <= segments; i++) {
  const u = i / segments;
  const r = 2 + 8 * u;
  const a = u * Math.PI * 2 * 7;
  pts.push([r * Math.cos(a), 0, r * Math.sin(a)]);
}
const coil = kit.mesh(
  kit.sweep(pts, 0.28),
  kit.mat("copper", { color: "#c47b43", metalness: 0.7, roughness: 0.34 })
);
return kit.at(coil, [0, -113.5, 0]);

